package com.pablo.controlgastos;

import android.app.Notification;import android.content.ComponentName;import android.os.Bundle;import android.service.notification.NotificationListenerService;import android.service.notification.StatusBarNotification;import java.text.Normalizer;import java.text.SimpleDateFormat;import java.util.*;import java.util.regex.*;

public class BankNotificationListener extends NotificationListenerService {
 private static volatile BankNotificationListener activeInstance;
 private static final Pattern MONEY=Pattern.compile("(?i)(U\\$S|USD|US\\$|\\$U|UYU|\\$)\\s*([0-9]+(?:[.,][0-9]{1,2})?|[0-9]{1,3}(?:[. ][0-9]{3})+(?:,[0-9]{1,2})?)");
 private static final Pattern BROU_IMPORTE=Pattern.compile("(?i)Importe\\s*:\\s*(UYU|USD|U\\$S|US\\$|\\$U|\\$)\\s*([0-9][0-9., ]*)"),BROU_COMERCIO=Pattern.compile("(?i)Comercio\\s*:\\s*([^\\n\\r]+)"),BROU_APROBADO=Pattern.compile("(?i)Aprobado\\s*:\\s*([0-9A-Za-z-]+)"),BROU_FECHA=Pattern.compile("(?i)Fecha\\s*:\\s*(\\d{4}-\\d{2}-\\d{2}\\s+\\d{2}:\\d{2}:\\d{2})"),PAGANZA_SERVICE=Pattern.compile("(?i)(?:servicio|empresa|comercio|beneficiario|concepto)\\s*:\\s*([^\\n\\r]+)"),PAGANZA_REFERENCE=Pattern.compile("(?i)(?:referencia|operaci[oó]n|comprobante|transacci[oó]n)\\s*:?\\s*([0-9A-Za-z-]+)");
 @Override public void onListenerConnected(){super.onListenerConnected();activeInstance=this;HourlyNotificationCheckReceiver.schedule(this);scanActiveNotifications();}@Override public void onListenerDisconnected(){activeInstance=null;super.onListenerDisconnected();}@Override public void onDestroy(){activeInstance=null;super.onDestroy();}public static void hourlyCheck(){BankNotificationListener i=activeInstance;if(i!=null)i.scanActiveNotifications();}public static boolean isConnected(){return activeInstance!=null;}public static boolean scanNow(){BankNotificationListener i=activeInstance;if(i==null)return false;i.scanActiveNotifications();return true;}public static void requestListenerReconnect(){try{requestRebind(new ComponentName("com.pablo.controlgastos.secure","com.pablo.controlgastos.BankNotificationListener"));}catch(Exception ignored){}}private void scanActiveNotifications(){try{StatusBarNotification[]a=getActiveNotifications();if(a!=null)for(StatusBarNotification s:a)processNotification(s);}catch(Exception ignored){}}@Override public void onNotificationPosted(StatusBarNotification sbn){processNotification(sbn);}
 private void processNotification(StatusBarNotification sbn){if(sbn==null||sbn.getNotification()==null)return;Bundle e=sbn.getNotification().extras;String title=s(e.getCharSequence(Notification.EXTRA_TITLE)),full=collectNotificationText(e);if(full.isEmpty())return;String all=title+"\n"+full;if(BlacklistRules.matches(this,all))return;String pkg=sbn.getPackageName()==null?"":sbn.getPackageName(),norm=normalizeKey(full),titleNorm=normalizeKey(title),pkgNorm=pkg.toLowerCase(Locale.ROOT);boolean fromPaganza=pkgNorm.contains("paganza")||titleNorm.contains("paganza"),mentionsPaganza=norm.contains("paganza");if(fromPaganza){processPaganza(sbn,title,full,norm);return;}if(mentionsPaganza)return;boolean custom=DetectionRules.matches(this,all);processBankNotification(sbn,title,full,norm,custom);}
 private void processBankNotification(StatusBarNotification sbn,String title,String full,String norm,boolean custom){if(!custom&&!(norm.contains("compra")||norm.contains("pago")||norm.contains("debito")||norm.contains("consumo")||norm.contains("transaccion")||norm.contains("transferencia")))return;if(norm.contains("anulad")||norm.contains("rechaz")||norm.contains("devolucion")||norm.contains("recibiste")||norm.contains("acredit"))return;String sym,raw;Matcher bi=BROU_IMPORTE.matcher(full);if(bi.find()){sym=bi.group(1);raw=bi.group(2).trim();}else{Matcher m=MONEY.matcher(full);if(!m.find())return;sym=m.group(1);raw=m.group(2).trim();}saveExpense(sbn,title,full,sym,raw);}
 private void processPaganza(StatusBarNotification sbn,String title,String full,String norm){if(!(norm.contains("pago")||norm.contains("pagaste")||norm.contains("pagado")||norm.contains("abonado")||norm.contains("debito")))return;if(norm.contains("rechaz")||norm.contains("fall")||norm.contains("pendiente")||norm.contains("venc")||norm.contains("recordatorio")||norm.contains("devolucion")||norm.contains("anulad"))return;Matcher m=MONEY.matcher(full);if(!m.find())return;String sym=m.group(1),raw=m.group(2).trim();double amount=parseLatam(raw.replace(" ",""));if(amount<=0)return;String upper=sym.toUpperCase(Locale.ROOT),currency=(upper.contains("USD")||upper.contains("U$S")||upper.contains("US$"))?"USD":"UYU";String description=title.isEmpty()?"Pago Paganza":title;Matcher sm=PAGANZA_SERVICE.matcher(full);if(sm.find())description=sm.group(1).trim();if(description.toLowerCase(Locale.ROOT).contains("paganza")&&description.length()<18)description="Pago Paganza";long ts=sbn.getPostTime()>0?sbn.getPostTime():System.currentTimeMillis();String unique="";Matcher rm=PAGANZA_REFERENCE.matcher(full);if(rm.find())unique="PAGANZA_REF:"+rm.group(1).trim();if(unique.isEmpty())unique="PAGANZA:"+sbn.getKey();ExpenseDb db=new ExpenseDb(this);if(db.existsOriginal(unique))return;if(db.hasImportedDuplicate("GASTO",amount,currency,description,ts))return;String cat=DetectionRules.categoryFor(this,title+" "+full,classifyPaganza(description));db.addTx("GASTO",amount,currency,cat,description,unique,ts,"notificacion:Paganza");}
 private void saveExpense(StatusBarNotification sbn,String title,String full,String sym,String raw){double amount=parseLatam(raw.replace(" ",""));if(amount<=0)return;String upper=sym.toUpperCase(Locale.ROOT),currency=(upper.contains("USD")||upper.contains("U$S")||upper.contains("US$"))?"USD":"UYU";String description=title.isEmpty()?"Notificación bancaria":title;Matcher cm=BROU_COMERCIO.matcher(full);if(cm.find())description=cm.group(1).trim();long ts=sbn.getPostTime()>0?sbn.getPostTime():System.currentTimeMillis();Matcher fm=BROU_FECHA.matcher(full);if(fm.find())try{ts=new SimpleDateFormat("yyyy-MM-dd HH:mm:ss",Locale.US).parse(fm.group(1)).getTime();}catch(Exception ignored){}String unique="";Matcher am=BROU_APROBADO.matcher(full);if(am.find())unique="BROU_APROBADO:"+am.group(1).trim();if(unique.isEmpty())unique="NOTIF:"+sbn.getKey();ExpenseDb db=new ExpenseDb(this);if(db.existsOriginal(unique))return;if(db.hasImportedDuplicate("GASTO",amount,currency,description,ts))return;String cat=DetectionRules.categoryFor(this,title+" "+full,"Sin categoría");db.addTx("GASTO",amount,currency,cat,description,unique,ts,"notificacion:"+sbn.getPackageName());}
 private static String classifyPaganza(String d){String s=normalizeKey(d);if(s.contains("ute")||s.contains("ose")||s.contains("antel")||s.contains("movistar")||s.contains("claro")||s.contains("internet"))return"Servicios";if(s.contains("contribucion")||s.contains("tribut")||s.contains("patente")||s.contains("sucive")||s.contains("intendencia"))return"Impuestos";if(s.contains("colegio")||s.contains("escuela")||s.contains("universidad"))return"Educación";if(s.contains("seguro")||s.contains("bse"))return"Seguros";return"Pagos";}private static String normalizeKey(String s){if(s==null)return"";return Normalizer.normalize(s,Normalizer.Form.NFD).replaceAll("\\p{M}","").toLowerCase(Locale.ROOT).replaceAll("\\s+"," ").trim();}private static String collectNotificationText(Bundle e){LinkedHashSet<String>p=new LinkedHashSet<>();add(p,e.getCharSequence(Notification.EXTRA_TITLE));add(p,e.getCharSequence(Notification.EXTRA_TEXT));add(p,e.getCharSequence(Notification.EXTRA_BIG_TEXT));add(p,e.getCharSequence(Notification.EXTRA_SUB_TEXT));add(p,e.getCharSequence(Notification.EXTRA_INFO_TEXT));add(p,e.getCharSequence(Notification.EXTRA_SUMMARY_TEXT));CharSequence[]l=e.getCharSequenceArray(Notification.EXTRA_TEXT_LINES);if(l!=null)for(CharSequence x:l)add(p,x);StringBuilder b=new StringBuilder();for(String x:p){if(b.length()>0)b.append('\n');b.append(x);}return b.toString().trim();}private static void add(Set<String>s,CharSequence x){if(x!=null){String v=x.toString().trim();if(!v.isEmpty())s.add(v);}}private static String s(CharSequence x){return x==null?"":x.toString();}private static double parseLatam(String x){try{int c=x.lastIndexOf(','),d=x.lastIndexOf('.');if(c>=0&&d>=0){if(c>d)x=x.replace(".","").replace(',','.');else x=x.replace(",","");}else if(c>=0)x=x.replace(".","").replace(',','.');else if(d>=0&&x.length()-d-1==3)x=x.replace(".","");return Double.parseDouble(x);}catch(Exception e){return-1;}}
}
